<?php $pageTitle='Student Dashboard'; require_once __DIR__.'/../includes/header.php';$st=$pdo->prepare("SELECT s.*,c.name class_name,c.section FROM students s LEFT JOIN classes c ON c.id=s.class_id WHERE s.user_id=?");$st->execute([user()['id']]);$s=$st->fetch();$a=$pdo->query("SELECT * FROM announcements WHERE audience IN ('all','students') AND (expires_at IS NULL OR expires_at>NOW()) ORDER BY published_at DESC LIMIT 5")->fetchAll();?>
<h2>Student Dashboard</h2><div class="card p-4 mb-4"><h5><?=e(trim(($s['surname']??'').' '.($s['firstname']??'')))?></h5><p class="mb-0">Admission No: <?=e($s['admission_no']??'')?> · Class: <?=e(trim(($s['class_name']??'').' '.($s['section']??'')))?></p></div><div class="card p-4"><h5>Announcements</h5><?php foreach($a as $x): ?><div class="border-bottom py-2"><strong><?=e($x['title'])?></strong><div><?=nl2br(e($x['body']))?></div></div><?php endforeach;?></div><?php require __DIR__.'/../includes/footer.php';